   if(res.context){const p=document.createElement('p');p.className='dictionary-note';p.textContent=res.context;box.append(p);}
   for(const passage of res.refs||[]){const b=document.createElement('button');b.type='button';b.className='dictionary-verse';b.textContent=passage;b.title='Leer el pasaje sin salir de MAUZI NOTE';b.onclick=()=>{hide();window.MauziBible?.open(passage,'RVR1960');};box.append(b);}
   for(const src of res.sources||[]){const line=document.createElement('div');line.className='source-citation';const label=document.createElement('strong');label.textContent=src.label;line.append(label);let u;try{u=new URL(src.url);}catch(_){continue;}
     const reference=document.createElement('small');reference.textContent=u.hostname+u.pathname;line.append(reference);box.append(line);
   }
   if(res.refs?.length){const p=document.createElement('small');p.textContent='Síntesis propia; no cita literal ni equivalencia automática de cada palabra griega.';box.append(p);}
   const suggestions=$('dictionarySuggestions');suggestions.replaceChildren();
   for(const other of res.suggestions||[]){const b=document.createElement('button');b.type='button';b.textContent=other.term;b.onclick=()=>lookup(other.term);suggestions.append(b);}
   pop.classList.remove('hidden');requestAnimationFrame(place);
